import json, sys, traceback, importlib
sys.path.insert(0, ".")
names = ["accounts","billing","contacts","customers","invoices","payments","returns","shipments"]
bad = 0
for name in names:
    mod = importlib.import_module("clients." + name)
    for i, ex in enumerate(json.load(open("examples/%s.json" % name))):
        rec = ex["record"]
        try:
            got = mod.normalize(rec)
            err = None
        except Exception as e:
            got, err = None, e
        exp = ex["result"]
        if "err" in exp:
            # expected failure; report the exception type if it is not a ValueError
            if err is None:
                bad += 1
                print("MISMATCH %s[%d]: expected %s, got ok %r" % (name, i, exp["err"], got))
            elif type(err).__name__ != exp["err"]:
                bad += 1
                print("ERRTYPE %s[%d]: expected %s, got %s: %s" % (name, i, exp["err"], type(err).__name__, err))
        else:
            if err is not None:
                bad += 1
                print("MISMATCH %s[%d]: expected ok, got %s: %s" % (name, i, type(err).__name__, err))
            elif got != exp["ok"]:
                bad += 1
                print("MISMATCH %s[%d]:" % (name, i))
                for k in sorted(set(got) | set(exp["ok"])):
                    if got.get(k, "<missing>") != exp["ok"].get(k, "<missing>"):
                        print("   %s: got %r want %r" % (k, got.get(k, "<missing>"), exp["ok"].get(k, "<missing>")))
print("failures:", bad)
